#include <algorithm>
#include <iostream>
#include <iterator>
#include <vector>

void println(const std::vector<int> &v) {
    for (int i : v)
        std::cout << i << ' ';
    std::cout << '\n';
}

int main() {
    std::vector<int> v1, v2, dest;

    v1 = {1, 2, 3, 4, 5};
    v2 = {3, 4, 5, 6, 7};

    std::set_union(
        v1.cbegin(), v1.cend(), v2.cbegin(), v2.cend(), std::back_inserter(dest));
    println(dest);

    dest.clear();

    v1 = {1, 2, 3, 4, 5, 5, 5};
    v2 = {3, 4, 5, 6, 7};

    std::set_union(
        v1.cbegin(), v1.cend(), v2.cbegin(), v2.cend(), std::back_inserter(dest));
    println(dest);
}
